mapper.select:
SELECT * FROM conversation
WHERE owner_id = #{userId} OR participant_id = #{userId}
ORDER BY updated_at DESC

mapper.update:
UPDATE chat_message
SET message  = #{message},
    is_img   = #{img},
    is_read  = #{read}
WHERE id = #{id}

UPDATE chat_message
SET is_read = 1
WHERE conversation_uuid = #{conversation_uuid}
  AND user_uuid != #{user_uuid}
  AND is_read = 0

mapper.select:
SELECT * FROM chat_message
WHERE conversation_uuid = #{conversation_uuid}
ORDER BY time ASC

